insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_67_v1'
from (values
('127.416.d.1.A',3,'A county asks a firm to redesign an intersection. The firm''s first design-process stage is to:','["define the traffic problem", "order the asphalt", "hold the ribbon cutting", "paint the crosswalks"]'::jsonb,0,'Design starts by defining the problem.','original'),
('127.416.d.1.A',4,'After testing a prototype culvert in a flume, the team returns to an earlier stage and changes the shape. This shows the design process is:','["finished", "iterative", "random", "linear"]'::jsonb,1,'Test results send teams back to revise.','original'),
('127.416.d.1.B',3,'A town with only 200,000 dollars for a footbridge must limit the design because of its available:','["weekends", "hobbies", "resources", "slogans"]'::jsonb,2,'Resources limit what can be built.','original'),
('127.416.d.1.B',4,'Choosing a cheaper but unsafe handrail to save money is mainly an issue of:','["branding", "color", "fashion", "ethics"]'::jsonb,3,'Safety cannot be traded for cost.','original'),
('127.416.d.1.C',3,'Residents who live beside a planned detention pond are stakeholders because the pond affects their:','["property and neighborhood", "lunch choices", "phone plans", "music taste"]'::jsonb,0,'Stakeholders are affected by the project.','original'),
('127.416.d.1.C',4,'A city that must approve and permit a development is a stakeholder with:','["no interest", "regulatory authority", "no influence", "only a social role"]'::jsonb,1,'Permitting agencies can stop or change a project.','original'),
('127.416.d.1.D',3,'A retaining wall cracks during a load test before construction. The crack is useful because it reveals a flaw:','["that never matters", "after it collapses", "before the real wall is built", "that cannot be fixed"]'::jsonb,2,'Failure in testing is cheap compared with failure in service.','original'),
('127.416.d.1.D',4,'Engineers study why the Tacoma Narrows Bridge failed so that later designs account for:','["toll prices", "paint chemistry", "sunset angles", "wind-induced vibration"]'::jsonb,3,'Failure analysis produces new design rules.','original'),
('127.416.d.2.A',3,'In project management, the phase in which the crew carries out the plan comes after initiating and planning and is called:','["executing", "forgetting", "archiving", "brainstorming"]'::jsonb,0,'Work happens during execution.','original'),
('127.416.d.2.A',4,'Monitoring and controlling compares actual progress with the plan so the manager can:','["erase the schedule", "correct deviations", "skip closing", "ignore the plan"]'::jsonb,1,'Control keeps the project on track.','original'),
('127.416.d.2.B',3,'On a civil project, the person with overall responsibility for schedule, budget, and team coordination is the:','["property neighbor", "delivery driver", "project manager", "receptionist"]'::jsonb,2,'The project manager coordinates the whole effort.','original'),
('127.416.d.2.B',4,'A project engineer who prepares calculations and drawings reports progress to the:','["vendor''s cashier", "news reporter", "competing firm", "project manager"]'::jsonb,3,'Team members report up to the manager.','original'),
('127.416.d.2.C',3,'Software that tracks tasks, deadlines, and costs for a construction job is a project:','["management tool", "music player", "photo filter", "recipe book"]'::jsonb,0,'Tools help track progress.','original'),
('127.416.d.2.C',4,'A team that needs to see which tasks overlap in time would most likely choose to display the schedule as a:','["family tree", "Gantt chart", "pie chart of lunch orders", "street map"]'::jsonb,1,'Gantt bars show overlap.','original'),
('127.416.d.2.D',3,'A change log noting who edited a drawing and on what date supports document:','["gossip", "advertising", "version control", "decoration"]'::jsonb,2,'Version control prevents use of outdated sheets.','original'),
('127.416.d.2.D',4,'Without a system for the project''s documents, a crew may build from an out-of-date drawing, which causes:','["faster approval", "better weather", "lower taxes", "costly rework"]'::jsonb,3,'Outdated documents lead to mistakes.','original'),
('127.416.d.2.E',3,'A client''s statement that a parking lot must hold 120 cars is an example of a project:','["requirement", "rumor", "hobby", "accident"]'::jsonb,0,'Requirements state what the project must achieve.','original'),
('127.416.d.2.E',4,'A deadline set by a grant, such as finishing before December 31, is a constraint that limits the project''s:','["logo", "schedule", "slogan", "name"]'::jsonb,1,'Constraints bound time, cost, and scope.','original'),
('127.416.d.2.F',3,'A budget for a small paving job lists materials, equipment, and:','["vacations", "trophies", "labor", "rumors"]'::jsonb,2,'Labor is a core cost category.','original'),
('127.416.d.2.F',4,'Materials cost 40,000 dollars, equipment 15,000 dollars, and labor 25,000 dollars. The total budget is:','["40,000 dollars", "65,000 dollars", "100,000 dollars", "80,000 dollars"]'::jsonb,3,'40,000 + 15,000 + 25,000 = 80,000.','original'),
('127.416.d.2.G',3,'A proposal to move a storm pipe 5 feet after the plans are approved should go through a formal:','["change review", "bake sale", "guess", "coin toss"]'::jsonb,0,'MOC controls modifications.','original'),
('127.416.d.2.G',4,'Management of change is important because a small shift can affect cost, schedule, and:','["the office carpet", "other design elements", "the staff directory", "the lunch menu"]'::jsonb,1,'Changes ripple through a design.','original'),
('127.416.d.3.A',3,'The owner of a project, who pays for it and sets its goals, is the project:','["tourist", "competitor", "client", "neighbor''s cousin"]'::jsonb,2,'The client drives the project''s objectives.','original'),
('127.416.d.3.A',4,'A lender who finances a development cares most that the project stays on budget and is:','["shortened to one page", "painted green", "renamed often", "completed as planned"]'::jsonb,3,'Financiers need the project to finish successfully.','original'),
('127.416.d.3.B',3,'The Texas Society of Professional Engineers and similar groups offer members networking and:','["professional development", "free vehicles", "guaranteed contracts", "tax exemptions"]'::jsonb,0,'Societies support learning and connections.','original'),
('127.416.d.3.B',4,'Joining an industry organization early in a career helps an engineer meet mentors and stay current on:','["celebrity news", "standards and practices", "fashion trends", "sports scores"]'::jsonb,1,'Membership keeps skills current.','original'),
('127.416.d.4.A',3,'A geotechnical engineer must understand soil behavior, while a structural engineer must understand how buildings resist:','["music genres", "pizza orders", "loads", "paint trends"]'::jsonb,2,'Each subdiscipline has its own core knowledge.','original'),
('127.416.d.4.A',4,'A water resources engineer''s core function is designing systems that manage rainfall runoff and:','["airline schedules", "radio signals", "street art", "water supply"]'::jsonb,3,'Water engineers handle supply and drainage.','original'),
('127.416.d.4.B',3,'A subdivision project needs input from civil subdisciplines such as drainage, transportation, and:','["structural and geotechnical", "musical", "theatrical", "culinary"]'::jsonb,0,'Projects combine several specialties.','original'),
('127.416.d.4.B',4,'A new shopping center''s driveway design and traffic study fall mainly under which civil subdiscipline?','["aerospace propulsion", "transportation engineering", "structural dynamics", "food chemistry"]'::jsonb,1,'Traffic and access are transportation topics.','original'),
('127.416.d.4.C',3,'Bridges, highways, dams, and water treatment plants are all examples of civil engineering:','["costumes", "songs", "projects", "recipes"]'::jsonb,2,'Civil engineers build infrastructure.','original'),
('127.416.d.4.C',4,'A project that moves clean water from a reservoir to homes through pipes and pumps is a:','["railway tunnel", "airport runway", "parking structure", "water supply system"]'::jsonb,3,'Distribution systems deliver water.','original'),
('127.416.d.5.A',3,'The Americans with Disabilities Act requires that public sidewalks and buildings be accessible, for example with:','["curb ramps", "raised thresholds", "narrower doors", "steeper steps"]'::jsonb,0,'ADA sets accessibility rules.','original'),
('127.416.d.5.A',4,'Under ADA guidelines, a wheelchair ramp slope is limited so a person can climb it safely. A common maximum ratio is:','["1:2", "1:12", "1:4", "1:1"]'::jsonb,1,'ADA ramps are generally 1 inch of rise per 12 inches of run.','original'),
('127.416.d.5.B',3,'A city''s zoning ordinance is a type of local regulation that controls how land may be:','["painted", "named", "used", "photographed"]'::jsonb,2,'Zoning controls land use.','original'),
('127.416.d.5.B',4,'To learn the setback requirements for a site, an engineer would consult the:','["weather almanac", "phone book", "sports almanac", "local development code"]'::jsonb,3,'Local codes list setbacks and limits.','original'),
('127.416.d.5.C',3,'A local rule limiting building height may force the design team to change the project''s:','["number of floors", "zip code", "owner''s name", "street name"]'::jsonb,0,'Codes shape the design.','original'),
('127.416.d.5.C',4,'Learning about local regulations early avoids redesign costs and permit:','["discounts", "delays", "savings", "bonuses"]'::jsonb,1,'Early awareness prevents rework.','original'),
('127.416.d.5.D',3,'A recorded map showing how a parcel is divided into lots and streets is a:','["menu", "poster", "plat", "playlist"]'::jsonb,2,'Plats show subdivisions.','original'),
('127.416.d.5.D',4,'A utility company''s right to run a power line across part of a private lot is called an:','["allowance", "entitlement", "amendment", "easement"]'::jsonb,3,'Easements grant limited use of land.','original'),
('127.416.d.6.A',3,'A feasibility report evaluates whether a project is technically, financially, and legally:','["possible", "colorful", "loud", "famous"]'::jsonb,0,'Feasibility asks if the project can succeed.','original'),
('127.416.d.6.A',4,'A feasibility report that finds the costs exceed the benefits would likely recommend that the client:','["skip all analysis", "not proceed as proposed", "double the budget", "hide the report"]'::jsonb,1,'Reports guide go or no-go decisions.','original'),
('127.416.d.6.B',3,'A scope of work document lists the services the firm will provide and the products it will:','["erase", "forget", "deliver", "trade"]'::jsonb,2,'Scope defines deliverables.','original'),
('127.416.d.6.B',4,'Vague scope language is risky because the client and firm may disagree about what work was:','["photographed", "sung", "painted", "promised"]'::jsonb,3,'Clear scope prevents disputes.','original'),
('127.416.d.6.C',3,'If an engineer bills 100 dollars per hour for 40 hours, the fee is:','["4,000 dollars", "10,000 dollars", "400 dollars", "140 dollars"]'::jsonb,0,'100 x 40 = 4,000.','original'),
('127.416.d.6.C',4,'A task takes 3 engineers 20 hours each at 90 dollars per hour. The labor value is:','["2,700 dollars", "5,400 dollars", "1,800 dollars", "540 dollars"]'::jsonb,1,'3 x 20 x 90 = 5,400.','original'),
('127.416.d.6.D',3,'When the client adds a new task after the draft proposal is written, the engineer revises the scope and fee and keeps the old version as an:','["secret", "joke", "archived copy", "advertisement"]'::jsonb,2,'Archiving preserves history.','original'),
('127.416.d.6.D',4,'Archiving each draft of a proposal lets the firm show what changed and:','["what the weather was", "who ate lunch", "which pen was used", "when it changed"]'::jsonb,3,'Archives document the change trail.','original'),
('127.416.d.6.E',3,'A client deliverable package for a proposal commonly includes a fee proposal, a schedule, and a:','["scope of work", "playlist", "recipe", "costume"]'::jsonb,0,'Packages bundle key documents.','original'),
('127.416.d.6.E',4,'Putting the fee proposal, schedule, and scope in one organized package helps the client compare the proposal against the:','["neighborhood events", "other firms'' offers", "lunch menu", "local weather"]'::jsonb,1,'Clients evaluate packages side by side.','original'),
('127.416.d.6.F',3,'When presenting a final proposal to a board, the engineer should speak clearly and keep slides:','["blank", "unrelated", "simple and focused", "packed with tiny text"]'::jsonb,2,'Clear delivery builds confidence.','original'),
('127.416.d.6.F',4,'A strong proposal presentation ends by stating what the firm will deliver and what it asks the client to:','["cook", "forget", "paint", "decide"]'::jsonb,3,'A clear call to action closes the pitch.','original'),
('127.416.d.6.G',3,'After losing a bid, a firm reviews how it pitched and priced the job to improve its next:','["proposal", "uniform", "parking pass", "lunch"]'::jsonb,0,'Reflection improves future work.','original'),
('127.416.d.6.G',4,'Recording lessons learned from each proposal helps a firm avoid repeating:','["correct prices", "past mistakes", "good ideas", "helpful steps"]'::jsonb,1,'Lessons carry forward.','original'),
('127.416.d.7.A',3,'The critical path is the longest chain of dependent tasks, which sets the project''s:','["color", "name", "minimum duration", "street address"]'::jsonb,2,'The critical path controls total time.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_67_v1'
from (values
('127.416.d.7.A',4,'Tasks that can slip without delaying the project completion date are not on the:','["budget", "drawing", "calendar", "critical path"]'::jsonb,3,'Non-critical tasks have float.','original'),
('127.416.d.7.B',3,'In a critical path diagram, arrows show which tasks must finish before others can:','["start", "be photographed", "be named", "be funded"]'::jsonb,0,'Arrows show dependencies.','original'),
('127.416.d.7.B',4,'Path A-B-D takes 10 days and path A-C-D takes 14 days. The shortest possible project duration is:','["24 days", "two weeks", "4 days", "10 days"]'::jsonb,1,'The longer path is critical.','original'),
('127.416.d.7.C',3,'After finding the critical path, the manager assigns start and finish dates to build the project:','["menu", "logo", "schedule", "slogan"]'::jsonb,2,'Dates turn the path into a schedule.','original'),
('127.416.d.7.C',4,'If a critical task slips three days and nothing else changes, the project end date moves by:','["1 day", "0 days", "10 days", "3 days"]'::jsonb,3,'Critical delays shift completion.','original'),
('127.416.d.7.D',3,'A Gantt chart shows each project activity as a bar along a:','["timeline", "menu", "coastline", "recipe"]'::jsonb,0,'The horizontal axis shows time.','original'),
('127.416.d.7.D',4,'On a Gantt chart, a longer bar means the activity takes:','["less time", "more time", "a different crew", "no time"]'::jsonb,1,'Bar length equals duration.','original'),
('127.416.d.7.E',3,'Looking at a schedule to find tasks that could run at the same time is a way to improve project:','["boredom", "cost overruns", "efficiency", "confusion"]'::jsonb,2,'Parallel work saves time.','original'),
('127.416.d.7.E',4,'Adding crews to a non-critical task will most likely not shorten the project because that task is not:','["a real activity", "assigned to anyone", "a task at all", "controlling the end date"]'::jsonb,3,'Only critical tasks shorten the finish.','original'),
('127.416.d.8.A',3,'A concept site plan is built from existing schematics, survey data, and the client''s:','["program needs", "favorite music", "fashion choices", "vacation photos"]'::jsonb,0,'Plans reflect site facts and needs.','original'),
('127.416.d.8.A',4,'Survey data on a concept site plan shows property lines, ground elevations, and existing:','["colors", "features", "moods", "rumors"]'::jsonb,1,'Surveys document what is there.','original'),
('127.416.d.8.B',3,'Electric, gas, water, and telecommunications companies that serve a site are called utility:','["competitors", "auditors", "providers", "tourists"]'::jsonb,2,'Utility providers must be coordinated.','original'),
('127.416.d.8.B',4,'An engineer contacts utility providers early to learn where lines are and what services can be:','["renamed", "canceled for the neighborhood", "hidden from the client", "extended to the site"]'::jsonb,3,'Early coordination avoids conflicts.','original'),
('127.416.d.8.C',3,'Before designing a new building, the team checks the county records for existing plats and:','["easements", "menus", "movie times", "fashion trends"]'::jsonb,0,'Easements restrict where building can occur.','original'),
('127.416.d.8.C',4,'Building on top of a utility easement without permission can lead to a forced:','["award", "removal of the structure", "bonus", "tax break"]'::jsonb,1,'Easement rights must be respected.','original'),
('127.416.d.8.D',3,'A final site plan is revised to reflect the analyzed site data, including drainage, utilities, and:','["slogans", "staff birthdays", "access and parking", "gossip"]'::jsonb,2,'Plans must incorporate analysis.','original'),
('127.416.d.8.D',4,'The final site plan should be checked against codes and easements before it is:','["renamed", "thrown away", "painted", "submitted for approval"]'::jsonb,3,'Review precedes submittal.','original'),
('127.416.d.9.A',3,'A storm with a 1 percent chance of occurring in any one twelve-month period is called a:','["100-year storm", "500-year storm", "10-year storm", "1-year storm"]'::jsonb,0,'A 100-year storm has a 1 in 100 annual chance.','original'),
('127.416.d.9.A',4,'Engineers use historical rainfall records to estimate how often storms of a given size are likely to:','["stop", "occur", "name themselves", "vanish"]'::jsonb,1,'Probability is based on past records.','original'),
('127.416.d.9.B',3,'The Rational method estimates peak runoff using a runoff coefficient, rainfall intensity, and the drainage:','["age", "color", "area", "owner"]'::jsonb,2,'Q = C i A.','original'),
('127.416.d.9.B',4,'A watershed has C = 0.5, i = 4 in/hr, and A = 10 acres. Using Q = CiA, the peak flow is:','["45 cfs", "200 cfs", "2 cfs", "20 cfs"]'::jsonb,3,'0.5 x 4 x 10 = 20.','original'),
('127.416.d.9.C',3,'Contour lines on a topographic map that are close together show a:','["steep slope", "wide road", "frozen lake", "flat plain"]'::jsonb,0,'Close contours mean rapid elevation change.','original'),
('127.416.d.9.C',4,'Runoff flows downhill and perpendicular to contour lines, so contours help an engineer find where water will:','["freeze", "drain", "evaporate only", "turn colors"]'::jsonb,1,'Contours reveal flow direction.','original'),
('127.416.d.9.D',3,'A drainage area map outlines the land that sends runoff to a single:','["road sign", "school", "outlet point", "property tax office"]'::jsonb,2,'Drainage areas are defined by outlets.','original'),
('127.416.d.9.D',4,'A new parking lot that redirects water into a neighboring watershed changes the boundary of the:','["utility bill", "zoning code", "site address", "drainage area"]'::jsonb,3,'Grading can shift drainage divides.','original'),
('127.416.d.9.E',3,'A detention pond reduces downstream flooding by holding stormwater and releasing it:','["slowly", "never", "instantly", "upward"]'::jsonb,0,'Detention slows the release rate.','original'),
('127.416.d.9.E',4,'Stormwater quality practices, such as vegetated swales, help remove pollutants and:','["rain clouds", "sediment", "speed limits", "utility lines"]'::jsonb,1,'Water quality controls filter runoff.','original'),
('127.416.d.9.F',3,'The existing flow rate for a storm is calculated before development so the team can compare it with the flow after:','["winter", "demolition of the sun", "construction", "retirement"]'::jsonb,2,'Pre- and post-development flows are compared.','original'),
('127.416.d.9.F',4,'A 100-year storm produces a larger peak flow than a 5-year storm because its rainfall intensity is:','["identical", "lower", "zero", "greater"]'::jsonb,3,'Rarer storms are more intense.','original'),
('127.416.d.9.G',3,'Adding pavement and roofs generally increases the runoff coefficient, so the proposed flow rate is typically:','["higher", "lower", "negative", "unchanged"]'::jsonb,0,'Impervious cover raises runoff.','original'),
('127.416.d.9.G',4,'Existing peak flow is 15 cfs and proposed peak flow is 21 cfs. The increase is:','["36 cfs", "6 cfs", "21 cfs", "15 cfs"]'::jsonb,1,'21 - 15 = 6.','original'),
('127.416.d.9.H',3,'If the proposed flow exceeds the existing flow, many cities require a facility to hold the:','["extra staff", "extra paperwork", "extra runoff", "extra parking"]'::jsonb,2,'Remediation limits post-development flow.','original'),
('127.416.d.9.H',4,'Sizing a detention pond for the 100-year storm helps ensure that downstream properties are protected during a:','["city parade", "school holiday", "sunny week", "severe rainfall event"]'::jsonb,3,'Ponds are designed for large storms.','original'),
('127.416.d.9.I',3,'Methods of moving stormwater include open channels, culverts, and:','["storm drain pipes", "bicycle racks", "fire hydrants", "street signs"]'::jsonb,0,'Conveyance carries flow.','original'),
('127.416.d.9.I',4,'A culvert is commonly used to carry water under a:','["fence post", "roadway", "rooftop", "swimming lane"]'::jsonb,1,'Culverts pass flow beneath roads.','original'),
('127.416.d.9.J',3,'The continuity equation says flow rate equals velocity times the:','["pipe color", "street length only", "cross-sectional area", "owner''s name"]'::jsonb,2,'Q = V A.','original'),
('127.416.d.9.J',4,'Water moves at 4 ft/s through a pipe with a flow area of 2 square feet. The flow rate is:','["0.5 cfs", "2 cfs", "6 cfs", "8 cfs"]'::jsonb,3,'4 x 2 = 8.','original'),
('127.416.d.9.K',3,'Designing a pipe means choosing a size and slope so it can carry the design flow without:','["overflowing", "draining", "existing", "flowing"]'::jsonb,0,'Capacity must meet demand.','original'),
('127.416.d.9.K',4,'If a pipe is too small for the design storm, the likely result is:','["lower costs forever", "surcharging and flooding", "cleaner water", "fewer permits"]'::jsonb,1,'Undersized pipes back up.','original'),
('127.416.d.9.L',3,'A plan and profile sheet shows the drainage layout from above and the pipe slope from the:','["dashboard", "inside", "side view", "phone"]'::jsonb,2,'Profiles show vertical information.','original'),
('127.416.d.9.L',4,'The profile portion of a drainage sheet is useful because it shows pipe elevations and the depth of:','["the engineer''s seal", "nearby shops", "paint on the pipe", "cover over the pipe"]'::jsonb,3,'Profiles show vertical relationships.','original'),
('127.416.d.9.M',3,'A drainage analysis that finds downstream flooding risk can change the final site:','["design", "owner", "address", "name"]'::jsonb,0,'Analysis results shape the design.','original'),
('127.416.d.9.M',4,'If the analysis shows too much runoff, the engineer may redesign the site to include more:','["parking", "green space or detention", "roofing", "pavement"]'::jsonb,1,'Mitigation reduces impact.','original'),
('127.416.d.10.A',3,'A geotechnical report typically includes boring logs, lab test results, and:','["paint samples", "advertising slogans", "foundation recommendations", "menu ideas"]'::jsonb,2,'Reports guide foundation design.','original'),
('127.416.d.10.A',4,'A boring log records the soil layers found at different depths and the depth of the:','["nearest park", "nearest school", "client''s office", "groundwater"]'::jsonb,3,'Boring logs show subsurface conditions.','original'),
('127.416.d.10.B',3,'The Unified Soil Classification System sorts soils into groups such as gravel, sand, silt, and:','["clay", "glass", "marble", "wood"]'::jsonb,0,'USCS groups soils by grain type.','original'),
('127.416.d.10.B',4,'A soil with more than half of its particles retained on the No. 200 sieve is classified as:','["organic only", "coarse-grained", "fine-grained", "frozen"]'::jsonb,1,'Coarse-grained soils are mostly large particles.','original'),
('127.416.d.10.C',3,'The plasticity index equals the liquid limit minus the:','["bearing load", "shrinkage rate", "plastic limit", "water table"]'::jsonb,2,'PI = LL - PL.','original'),
('127.416.d.10.C',4,'A soil has a liquid limit of 45 and a plastic limit of 25. Its plasticity index is:','["70", "45", "25", "20"]'::jsonb,3,'45 - 25 = 20.','original'),
('127.416.d.10.D',3,'Compacting soil in layers before building increases its density and:','["strength", "moisture only", "volume of voids", "slope"]'::jsonb,0,'Compaction improves support.','original'),
('127.416.d.10.D',4,'Replacing weak clay under a slab with compacted select fill is a method of site:','["landscaping", "soil preparation", "decoration", "marketing"]'::jsonb,1,'Over-excavation improves bearing.','original'),
('127.416.d.10.E',3,'Soils with high plasticity swell and shrink, which can crack the surface of a:','["rainbow", "computer", "pavement", "document"]'::jsonb,2,'Expansive clays damage roads.','original'),
('127.416.d.10.E',4,'A geotechnical report that finds weak subgrade soils may recommend a thicker base course or soil:','["additional mulch", "relocation of the sun", "decoration", "stabilization"]'::jsonb,3,'Pavement design depends on subgrade strength.','original'),
('127.416.d.10.F',3,'The best pavement section for a heavily loaded truck route is chosen by comparing strength, cost, and expected:','["traffic loads", "advertising", "sidewalk art", "paint colors"]'::jsonb,0,'Pavement design depends on loading.','original'),
('127.416.d.10.F',4,'Choosing between asphalt and concrete pavement should consider initial cost, life-cycle cost, and:','["owner''s age", "maintenance needs", "bus colors", "city motto"]'::jsonb,1,'Life-cycle thinking guides selection.','original')
